"""A focused next-action inbox; no ambient monitoring or hidden model calls."""
OBLIGATION_CSS = r"""
.obligation-list{display:grid;gap:16px;margin-top:20px}.obligation-card{border:1px solid var(--line);border-radius:20px;padding:22px;background:var(--panel)}
.obligation-card header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.obligation-card h3{margin:12px 0 6px;font-size:20px}.obligation-card p{line-height:1.6;max-width:75ch;overflow-wrap:anywhere}.obligation-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:16px}
.obligation-consent{display:flex;align-items:flex-start;gap:10px;line-height:1.5;font-size:13px;color:var(--muted);margin:18px 0}.obligation-consent input{margin-top:4px;flex-shrink:0}.obligation-brief{background:var(--panel2);border-radius:16px;padding:16px;margin-top:16px}.obligation-brief p{margin:6px 0}.obligation-summary{font-size:14px;color:var(--muted)}
"""

OBLIGATION_JS = r"""
      // One obligation -> selected evidence -> one checked Gemini task -> result.
      // Selection is explicit consent, never a payment authorization.
      const obligationIntro='Keep your bills on track. Friday prepares the next safe step and records the outcome.';
      everydayIntroCopy.textContent=obligationIntro;
      const obligationLabels={READY_TO_PREPARE:'Ready to prepare · not paid',RECORDED_COMPLETE:'Recorded artificial payment',DETAILS_CONFLICT:'Details disagree · not a fraud verdict',VERIFY_STATUS:'Check payment status first',NEEDS_DETAILS:'Details needed',VERIFY_PROVIDER:'Provider verification needed',REVIEW_RULES:'Outside the current plan'};
      const obligationConsent=element('input');obligationConsent.type='checkbox';
      const obligationConsentLabel=element('label',null,'obligation-consent');obligationConsentLabel.append(obligationConsent,element('span','When I choose Prepare, share this selected obligation, its document claims, artificial provider record and my rules with Gemini. Preparation does not pay.'));
      const obligationInstruction=element('input');obligationInstruction.type='text';obligationInstruction.maxLength=1000;obligationInstruction.className='goal';obligationInstruction.placeholder='Optional: what should Friday focus on?';obligationInstruction.setAttribute('aria-label','Instruction for the selected obligation');
      const obligationSummary=element('p',null,'obligation-summary');obligationSummary.setAttribute('role','status');
      const obligationCards=element('div',null,'obligation-list');
      reviewHeading.textContent='What needs handling?';
      reviewView.replaceChildren(reviewHeading,element('p','One obligation, one next step. Friday never treats your uploaded receipt as bank settlement.'),obligationSummary,obligationInstruction,obligationConsentLabel,reviewRefresh,obligationCards,csvPanel);
      let obligationLoading=false;
      function obligationTone(item){return item.state==='RECORDED_COMPLETE'?'pass':item.state==='READY_TO_PREPARE'?'live':item.state==='DETAILS_CONFLICT'?'held':'review';}
      function obligationValid(data){return data.scope==='FINANCIAL_OBLIGATION_WORKSPACE'&&data.money_moved===false&&data.payment_authorized===false&&Array.isArray(data.items)&&typeof data.evidence_version==='string';}
      function obligationAction(item,data){
        const button=element('button',item.action==='ADD_DETAILS'?'Add readable details':item.action==='CHECK_RECORDED_RESULT'?'Review recorded outcome':item.action==='PREPARE_PAYMENT'?'Prepare this bill':'Prepare verification','planner');button.type='button';
        button.addEventListener('click',()=>{
          if(item.action==='ADD_DETAILS'){show('document');return;}
          if(item.action==='CHECK_RECORDED_RESULT'){openObligationResult(item);return;}
          if(!obligationConsent.checked){show('review');obligationConsent.focus();toast('Confirm selected-context sharing before preparing with Gemini.');return;}
          const intention=item.action==='PREPARE_PAYMENT'?'Prepare the exact artificial provider bill for review; do not pay yet.':'Prepare a useful UNSENT verification message. Ask specific questions about missing evidence or conflicting details; do not pay or assert fraud.';
          prepareTaskRequest({message:intention+' '+obligationInstruction.value.trim(),include_workspace:true,obligation_id:item.obligation_id,expected_evidence_version:data.evidence_version});
        });return button;
      }
      async function openObligationResult(item){show('assistant');taskPanel.replaceChildren(element('h2','Checking the recorded result…'),element('p','No Gemini call or new payment.'));
        try{const result=await jsonRequest('/api/friday/obligations/'+item.obligation_id+'/result');if(result.scope!=='ARTIFICIAL_OBLIGATION_RESULT'||result.read_only!==true||result.new_payment_created!==false||result.money_moved!==false)throw new Error('Unexpected authority');const verified=result.state==='RECORDED_PAYMENT_VERIFIED'&&result.signature_verified===true;const badge=element('span',verified?'Recorded artificial payment':'Outcome not confirmed','friday-task-state');badge.dataset.tone=verified?'pass':'review';taskPanel.replaceChildren(badge,element('h2',verified?'Already handled. No need to pay again.':'Check the evidence before another payment.'),element('p',result.message));if(verified){const fields=element('dl',null,'friday-task-detail');[['Bill',result.bill_reference],['Artificial amount',taskAmount(result.amount_minor)],['Test provider',result.supplier],['Recipient',result.recipient]].forEach(([name,value])=>{const pair=element('div');pair.append(element('dt',name),element('dd',value));fields.append(pair);});taskPanel.append(fields);if(result.document_checks.length)taskPanel.append(element('p','Other document claims still need review: '+result.document_checks.join(', ')));}taskPanel.append(element('p','This confirms only the internal artificial-payment journal, not real-bank settlement. No new payment was created.'));const back=element('button','Back to financial inbox','planner');back.type='button';back.dataset.screenLink='review';taskPanel.append(back);}catch{taskError('The recorded outcome could not be verified. No retry or new payment was submitted.');}}
      function obligationCard(item,data,compact=false){
        const card=element('article',null,'obligation-card');const header=element('header');const badge=element('span',obligationLabels[item.state]||'Verification needed','friday-task-state');badge.dataset.tone=obligationTone(item);header.append(badge);
        if(Number.isSafeInteger(item.amount_minor))header.append(element('b',reviewMoney(item.amount_minor,item.currency,{INR:2,USD:2,EUR:2,GBP:2,AUD:2,SGD:2,JPY:0})));
        card.append(header,element('h3',item.supplier||'Supplier not established'),element('small','Reference: '+(item.reference||'Not supplied')),element('p',compact?item.next_step:item.why));
        if(!compact){const next=element('section',null,'obligation-brief');next.append(element('b','What Friday can do next'),element('p',item.next_step));card.append(next);const details=element('details');details.append(element('summary','Evidence boundary & verification questions'),element('p',item.provider_evidence==='ARTIFICIAL_RECORD_MATCH'?'Exact supplier and reference matched an artificial provider record. That is not real merchant verification.':'No exact provider record is connected. An uploaded bill does not create payment authority.'));(item.comparisons||[]).forEach(row=>details.append(element('p',row.field.replaceAll('_',' ')+': document claim '+String(row.claim??'Not established')+' · artificial provider '+String(row.artificial_provider_value)+' · '+row.state.replaceAll('_',' ').toLowerCase()+(row.field==='amount_minor'?' (minor units)':''))));item.verification_questions.forEach(question=>details.append(element('p',question)));item.checks.forEach(code=>details.append(element('p',reviewReasons[code]||code)));details.append(element('p','Recipient ownership and external settlement are not verified.'));card.append(details);}
        if(!compact&&(item.source_evidence||[]).length){const evidence=element('details');evidence.append(element('summary','Show source quotations & OCR grounding'));item.source_evidence.forEach(source=>{evidence.append(element('h4','Saved input · '+source.document_id.slice(-8)),element('p',source.mode));if(source.grounding?.mode==='DOCUMENT_AI_OCR'){evidence.append(element('p','Independent Google OCR text anchors. This is not proof that the issuer or recipient is genuine.'));(source.grounding.field_anchors||[]).forEach(anchor=>evidence.append(element('blockquote',anchor.field+': “'+anchor.quote+'” · page '+[...new Set(anchor.locations.map(location=>location.page))].join(', '))));if(source.grounding.unsupported_fields.length)evidence.append(element('p','Fields still ungrounded: '+source.grounding.unsupported_fields.join(', ')));}else source.quotes.forEach(quote=>evidence.append(element('blockquote',quote.field+': “'+quote.quote+'”')));});evidence.append(element('p','Up to ten source records shown here; safety checks cover the complete bounded evidence. Source quotations are not bank settlement.'));card.append(evidence);}
        const actions=element('div',null,'obligation-actions');if(compact){const open=element('button','See next step','planner');open.type='button';open.dataset.screenLink='review';actions.append(open);}else actions.append(obligationAction(item,data));card.append(actions);return card;
      }
      async function refreshObligations(){if(obligationLoading)return;obligationLoading=true;reviewRefresh.disabled=true;obligationSummary.textContent='Checking saved claims, artificial provider records and recorded outcomes. No Gemini call or payment.';
        try{const data=await jsonRequest('/api/friday/obligations');if(!obligationValid(data))throw new Error('Unexpected obligation authority');obligationCards.replaceChildren();const personal=data.items.filter(item=>item.source_case_id);const demo=data.items.filter(item=>!item.source_case_id);if(!personal.length){obligationCards.append(element('p','Your records start here. Add your own bill or request, or open the optional artificial examples below. Friday will not invent personal obligations.'));const add=element('button','Add a financial input','planner');add.type='button';add.dataset.screenLink='bill';obligationCards.append(add);}personal.forEach(item=>obligationCards.append(obligationCard(item,data)));if(demo.length){const examples=element('details');examples.append(element('summary','Artificial provider examples (optional)'),element('p','These test-provider records are not your real bills or bank history. They demonstrate restricted artificial-money execution.'));demo.forEach(item=>examples.append(obligationCard(item,data)));obligationCards.append(examples);}
          obligationSummary.textContent=personal.length+' saved obligation(s) · '+data.coverage.documents_checked+' inputs checked · '+demo.length+' optional artificial provider records. No real accounts are connected.';
        }catch(error){obligationCards.replaceChildren();obligationSummary.textContent='Complete evidence is unavailable. No task or payment was submitted. Retry the read-only refresh.';}finally{obligationLoading=false;reviewRefresh.disabled=false;}}
      // Both routes share this projection; older display-only review remains in API.
      reviewRefresh.removeEventListener('click',refreshReviews);refreshReviews=refreshObligations;reviewRefresh.addEventListener('click',refreshObligations);
      refreshEverydayHome=async()=>{if(everydayPreviewBusy)return;everydayPreviewBusy=true;everydayStatus.textContent='Checking your next steps…';try{const data=await jsonRequest('/api/friday/obligations');if(!obligationValid(data))throw new Error('Unexpected response');const personal=data.items.filter(item=>item.source_case_id);inboxLabel.textContent='Your next steps';inboxCount.textContent=personal.length+' saved obligation(s)';everydayRows.replaceChildren();if(!personal.length)everydayRows.append(element('p','Ask Friday a question or add one financial request. Optional artificial examples are separate from your personal records.','everyday-empty'));personal.slice(0,3).forEach(item=>everydayRows.append(obligationCard(item,data,true)));everydayStatus.textContent='No background bank monitoring. Green means a verified artificial journal result—not a safe-merchant guarantee.';}catch(error){everydayRows.replaceChildren();everydayStatus.textContent='Next steps unavailable. No successful task is assumed.';}finally{everydayPreviewBusy=false;}};
      const obligationExamples=home.querySelector('.friday-start-grid');if(obligationExamples){const copy=obligationExamples.previousElementSibling;if(copy?.tagName==='P')copy.textContent='Understand the request, prepare the next safe step, and follow the outcome. Questions are read-only; only the sandbox can move artificial money.';}
      const heading=home.querySelector('.everyday-hero h1');if(heading)heading.textContent='Your obligations. Handled with care.';
      const beforeObligationShow=show;show=function(name,push=true){beforeObligationShow(name,push);if(name==='home')everydayIntroCopy.textContent=obligationIntro;};
"""
